type Tab='search'|'upload'|'batches'|'trash'|'sects'|'temples'|'statistics'|'help';
type Row={sequence:string;certificate_number?:string;vassa:number|null;birth_year:number|null;age_at_exam:number|null;birth_year_estimated:number;age_estimated:number;id:string;year:number;province:string;region:string;sect:string;category:string;level:string;title:string;first_name:string;last_name:string;dharma_name:string;temple:string;district:string;subdistrict:string;source_province:string;school:string;note:string;sheet:string;source_row:number;filename:string;batch_id:string;updated_at:string;batch_status?:string;[key:string]:unknown};
type Batch={vassa_status?:string;vassa_updated?:number;vassa_error?:string;age_status?:string;age_updated?:number;age_error?:string;visibility:string;summary:string;id:string;province:string;year:number;filename:string;status:string;total:number;valid:number;issues:number;inserted:number;created_at:string;committed_at:string};
type Preview={batch:Batch;records:PassRecord[];issues:PassRecord[];issueTotal:number;recordsTotal:number;recordPage:number;recordPages:number;issuePage:number;issuePages:number;groups:ParsedFile['groups'];ignored:number;warnings:string[];holds?:string[];autoReady?:boolean;reconciliation?:{declared:number|null;found:number;matches:boolean|null};organizationSummary?:OrganizationSummary;registrySummary?:RegistrySummary};
type Stats={total:number;provinces:number;years:number;monastic:number;lay:number;regions:number;maha:number;dhammayut:number;unknown_sect:number};
const nf=new Intl.NumberFormat('th-TH-u-nu-thai');const num=(v:number|undefined)=>nf.format(v||0);
const date=(s:string)=>s?new Intl.DateTimeFormat('th-TH',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Bangkok'}).format(new Date(s)):'—';
type ApiResponse = {error?:string;stats:Stats;years:number[];regions:string[];user:{name:string;email:string};batch:Batch & {latest:string};items:Row[] & Batch[];total:number;page:number;pages:number;existing?:boolean;autoCommitted?:boolean;autoPending?:boolean;visibility:string;status?:string;id:string;done:boolean;inserted:number;deletedRecords?:number;storageCleaned?:boolean;filename?:string;updatedRecords?:number;checkedRecords?:number;records:PassRecord[];issues:PassRecord[];issueTotal:number;recordsTotal:number;recordPage:number;recordPages:number;issuePage:number;issuePages:number;groups:Preview['groups'];ignored:number;warnings:string[];organizationSummary?:OrganizationSummary;registrySummary?:RegistrySummary;record:Row;changes:{action:string;detail:string;created_at:string}[]};
async function api(params:string|URLSearchParams,options?:RequestInit){const res=await fetch('/api/passlist?'+params,options);const data=await res.json() as ApiResponse;if(!res.ok)throw new Error(data.error||'ไม่สามารถเชื่อมต่อได้');return data;}
const post=(body:unknown)=>api('',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
function Select({label,value,onChange,options,placeholder='ทั้งหมด',required=false}:{label:string;value:string;onChange:(s:string)=>void;options:string[];placeholder?:string;required?:boolean}){return <ThaiNumerals><label className="field"><span>{label}</span><select value={value} onChange={e=>onChange(e.target.value)} required={required}><option value="">{placeholder}</option>{options.map(s=><option key={s} value={s}>{s==='certificate_asc'?'เลขที่ ปกศ. น้อยไปมาก':s==='certificate_desc'?'เลขที่ ปกศ. มากไปน้อย':provinceLabel(s)}</option>)}</select></label></ThaiNumerals>}
function Modal({children,onClose,title}:{children:ReactNode;onClose:()=>void;title:string}){const ref=useRef<HTMLDialogElement>(null);useEffect(()=>{ref.current?.showModal();},[]);return <ThaiNumerals><dialog ref={ref} onCancel={onClose} className="modal"><header><h2>{title}</h2><button className="icon-button" onClick={onClose} aria-label="ปิด"><X size={21}/></button></header>{children}</dialog></ThaiNumerals>}
function scopeLabel(b:Batch){if(b.province!=='อ่านจากไฟล์')return b.province;try{const groups=JSON.parse(b.summary||'{}').groups||[];const provinces=new Set(groups.map((g:{province:string})=>g.province).filter(Boolean));return `อ่านจากไฟล์ · ${provinces.size} จังหวัด`;}catch{return b.province;}}
function batchYear(b:Batch){if(b.year)return String(b.year);try{const years=JSON.parse(b.summary||'{}').years||[];return years.length===1?String(years[0]):'';}catch{return '';}}
const statusLabel:Record<string,string>={draft:'รอตรวจทาน',importing:'นำเข้ายังไม่ครบ',committed:'นำเข้าแล้ว',archived:'เก็บออกแล้ว'};
function RegistrySummaryBox({value,downloadId}:{value?:RegistrySummary|null;downloadId?:string}){if(!value)return null;return <ThaiNumerals><div className={value.ready?'reconcile-box':'reconcile-box bad'}><strong>{value.ready?'ผลตรวจเทียบทะเบียนวัด':'ยังเทียบทะเบียนวัดไม่ได้'}</strong>: {value.ready?`ตรวจ ${num(value.checked)} แถว · ตรงทะเบียน ${num(value.matched)} · เติมอัตโนมัติ ${num(value.autoFilledRecords)} รายการ (ตำบล ${num(value.autoFilledSubdistrict)} · จังหวัด ${num(value.autoFilledProvince)} · นิกาย ${num(value.autoFilledSect)}) · นิกายขัดแย้ง ${num(value.sectConflict)} · นิกายอื่น ${num(value.otherSect)} · ชื่อหรือพื้นที่กำกวม ${num(value.ambiguous)} · พื้นที่ต่าง ${num(value.locationMismatch)} · ไม่พบชื่อ ${num(value.notFound)} · พื้นที่ไม่ครบ ${num(value.incomplete)} · ไม่มีชื่อวัด ${num(value.missingTemple)}`:`นำเข้าในฐานข้อมูลแล้ว ${num(value.total)} / ${num(value.expected)} แถว`}{value.ready&&downloadId?<a className="text-button registry-report-link" href={'/api/passlist?action=registry-report&id='+encodeURIComponent(downloadId)}><Download size={15}/>รายงานเทียบครบทุกแถว</a>:null}</div></ThaiNumerals>}
function OrganizationSummaryBox({value}:{value?:OrganizationSummary|null}){if(!value)return null;return <ThaiNumerals><div className={value.ready?'reconcile-box':'reconcile-box bad'}><strong>ผลเทียบองค์กรและสถานศึกษา</strong>: ตรงทะเบียน {num(value.matched)} · เติมที่อยู่ {num(value.autoFilledRecords)} รายชื่อ (ตำบล {num(value.autoFilledSubdistrict)} · อำเภอ {num(value.autoFilledDistrict)} · จังหวัด {num(value.autoFilledProvince)}) · ชื่อซ้ำต่างพื้นที่ {num(value.ambiguous)} · ที่อยู่ขัดแย้ง {num(value.locationMismatch)} · ไม่พบชื่อ {num(value.notFound)}</div></ThaiNumerals>;}
export default function PasslistApp({role='admin'}:{role?:'admin'|'editor'|'viewer'}){
 const [previewSize,setPreviewSize]=useState(25);
 const [pageSize,setPageSize]=useState(25),[trashSize,setTrashSize]=useState(25),[batchSize,setBatchSize]=useState(25),[batchPaging,setBatchPaging]=useState({page:1,pages:0,total:0});
 const [tab,setTab]=useState<Tab>('search'),[stats,setStats]=useState<Stats>(),[years,setYears]=useState<number[]>([]),[knownRegions,setKnownRegions]=useState<string[]>([]),[latest,setLatest]=useState(''),[user,setUser]=useState({name:'',email:''}),[error,setError]=useState(''),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false),[loading,setLoading]=useState(true);
 const [registryStatus,setRegistryStatus]=useState<TempleRegistryStatus|null>(null),[completeRegistry,setCompleteRegistry]=useState<RegistrySummary|null>(null);
 const [organizationStatus,setOrganizationStatus]=useState<OrganizationRegistryStatus|null>(null),[completeOrganization,setCompleteOrganization]=useState<OrganizationSummary|null>(null);
 const [query,setQuery]=useState(''),[province,setProvince]=useState(''),[year,setYear]=useState(''),[category,setCategory]=useState(''),[level,setLevel]=useState(''),[sort,setSort]=useState('certificate_asc'),[region,setRegion]=useState(''),[sect,setSect]=useState(''),[applied,setApplied]=useState(new URLSearchParams()),[page,setPage]=useState(1),[results,setResults]=useState<{items:Row[];total:number;page:number;pages:number}>({items:[],total:0,page:1,pages:0});
 const [trashResult,setTrashResult]=useState<{items:Row[];total:number;page:number;pages:number}>({items:[],total:0,page:1,pages:0});
 const [batchList,setBatchList]=useState<Batch[]>([]),[preview,setPreview]=useState<Preview|null>(null),[upProvince,setUpProvince]=useState(''),[upYear,setUpYear]=useState(''),[upCategory,setUpCategory]=useState(''),[upLevel,setUpLevel]=useState(''),[upRegion,setUpRegion]=useState(''),[upSect,setUpSect]=useState(''),[useSourceProvince,setUseSourceProvince]=useState(false),[upJurisdiction,setUpJurisdiction]=useState(''),[upSchool,setUpSchool]=useState(''),[automatic,setAutomatic]=useState(true),[publishAfter,setPublishAfter]=useState(false),[file,setFile]=useState<File|null>(null),[drag,setDrag]=useState(false),[ack,setAck]=useState(false),[exclude,setExclude]=useState(false),[progress,setProgress]=useState(0),[issueView,setIssueView]=useState(true),[complete,setComplete]=useState<Batch|null>(null);
 const [deferSect,setDeferSect]=useState(true),[reviewBatch,setReviewBatch]=useState('');
 const [jurisdiction,setJurisdiction]=useState(''),[schoolFilter,setSchoolFilter]=useState(''),[kindFilter,setKindFilter]=useState('');
 const [detail,setDetail]=useState<{record:Row;changes:{action:string;detail:string;created_at:string}[]}|null>(null),[editing,setEditing]=useState(false);
 const [editProvince,setEditProvince]=useState(''),[editSchool,setEditSchool]=useState(''),[autoSchool,setAutoSchool]=useState(false);
 const fetchStats=useCallback(async()=>{const d=await api('action=stats');setStats(d.stats);setYears(d.years);setKnownRegions(d.regions||[]);setUser(d.user);setLatest(d.batch.latest||'');},[]);
 const fetchBatches=useCallback(async(p=1)=>{const d=await api('action=batches&page='+p+'&pageSize='+batchSize);setBatchList(d.items);setBatchPaging({page:d.page,pages:d.pages,total:d.total});},[batchSize]);
 const fetchTrash=useCallback(async(p=1)=>{const d=await api('action=trash&page='+p+'&pageSize='+trashSize);setTrashResult({items:d.items,total:d.total,page:d.page,pages:d.pages});},[trashSize]);
 const fetchResults=useCallback(async(params:URLSearchParams,p:number,signal?:AbortSignal)=>{setLoading(true);try{const q=new URLSearchParams(params);q.set('page',String(p));q.set('pageSize',String(pageSize));const d=await api(q,{signal});setResults(d);}catch(e){if(!(e instanceof Error&&e.name==='AbortError'))setError(String((e as Error).message));}finally{if(!signal?.aborted)setLoading(false);}},[pageSize]);
 useEffect(()=>{fetchStats().catch(e=>setError(e.message));},[fetchStats]);
 useEffect(()=>{const c=new AbortController();fetchResults(applied,page,c.signal);return()=>c.abort();},[applied,page,fetchResults]);
 useEffect(()=>{if(tab==='batches')fetchBatches().catch(e=>setError(e.message));if(tab==='trash')fetchTrash(trashResult.page).catch(e=>setError(e.message));},[tab,fetchBatches,fetchTrash,trashResult.page]);
 function navigate(t:Tab){if(busy)return;if(t==='sects')setReviewBatch('');setError('');setNotice('');setTab(t);}
 function search(e:FormEvent){e.preventDefault();const p=new URLSearchParams();for(const [k,v]of Object.entries({q:query,province,year,category,level,region,sect,sort,jurisdiction,school:schoolFilter,schoolKind:kindFilter}))if(v)p.set(k,v);setApplied(p);setPage(1);setError('');}
 function reset(){setJurisdiction('');setSchoolFilter('');setKindFilter('');setQuery('');setProvince('');setYear('');setCategory('');setLevel('');setRegion('');setSect('');setSort('certificate_asc');setApplied(new URLSearchParams());setPage(1);}
 async function loadPreview(id:string,deferred=deferSect){const d=await api('action=preview&id='+encodeURIComponent(id)+'&deferSect='+String(deferred)+'&pageSize='+previewSize);setPreview(d);setPublishAfter(false);setAck(false);setExclude(false);setProgress(Math.round((d.batch.inserted/d.batch.valid||0)*100));setComplete(null);setCompleteRegistry(null);setTab('upload');}
 async function pagePreview(page:number,size=previewSize){if(!preview)return;setBusy(true);setError('');try{const d=await api(new URLSearchParams({action:'preview',id:preview.batch.id,deferSect:String(deferSect),page:String(page),pageSize:String(size)}));setPreview(d);}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function upload(e:FormEvent){e.preventDefault();if(!file){setError('กรุณาเลือกไฟล์ Excel');return;}if(!organizationStatus?.ready){setError('ทะเบียนองค์กรและสถานศึกษากำลังนำเข้า กรุณารอให้ทะเบียนครบก่อน');return;}if(!registryStatus?.ready){setError('ทะเบียนวัดอ้างอิงยังติดตั้งไม่ครบ กรุณารอให้ระบบนำเข้าทะเบียนเสร็จก่อน');return;}setBusy(true);setError('');try{const f=new FormData();f.set('file',file);f.set('province',upProvince);f.set('year',upYear);f.set('category',upCategory);f.set('level',upLevel);f.set('region',upRegion);f.set('sect',deferSect?'':upSect);f.set('deferSect',String(deferSect));f.set('useSourceProvince',String(useSourceProvince));f.set('automatic',String(automatic));f.set('jurisdiction',upJurisdiction);f.set('school',upSchool);const d=await api('',{method:'POST',body:f});if(d.autoPending){let result=d,round=0;setProgress(Math.round((d.inserted/d.total)*100));while(!result.done&&round++<22){result=await post({action:'commit',id:d.id,acknowledge:true,excludeErrors:false,publish:!deferSect,deferSect,automatic:true});setProgress(Math.round((result.inserted/result.total)*100));}if(!result.done)throw new Error('ยังนำเข้าไม่ครบ กรุณากดนำเข้าต่อ');const previewData=await api('action=preview&id='+d.id);setCompleteRegistry(previewData.registrySummary||d.registrySummary||null);setCompleteOrganization(previewData.organizationSummary||d.organizationSummary||null);setComplete(previewData.batch);setPreview(null);setFile(null);await fetchStats();}else if(d.autoCommitted){const previewData=await api('action=preview&id='+d.id);setCompleteRegistry(previewData.registrySummary||d.registrySummary||null);setCompleteOrganization(previewData.organizationSummary||d.organizationSummary||null);setComplete(previewData.batch);setPreview(null);setFile(null);await fetchStats();}else if(d.existing&&d.status==='committed'){setNotice('ไฟล์นี้นำเข้าแล้ว ระบบป้องกันการเพิ่มซ้ำ คุณตรวจสอบได้ในชุดข้อมูล');setTab('batches');await fetchBatches();}else if(d.status==='archived'){setNotice('ไฟล์นี้อยู่ในชุดข้อมูลที่เก็บออกแล้ว กดคืนชุดข้อมูลเพื่อใช้งานต่อ');setTab('batches');await fetchBatches();}else{await loadPreview(d.id);if(automatic)setNotice('ข้อมูลมีรายการที่ต้องตรวจทาน จึงพักการนำเข้าและเผยแพร่อัตโนมัติไว้ก่อน');}}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function commit(){if(!preview)return;setBusy(true);setError('');try{let done=false;let n=0;let visibility='internal';while(!done&&n++<520){const d=await post({action:'commit',id:preview.batch.id,acknowledge:ack,excludeErrors:exclude,publish:publishAfter,deferSect});visibility=d.visibility;setProgress(Math.round(d.inserted/d.total*100));done=d.done;}if(!done)throw new Error('ยังนำเข้าไม่ครบ กรุณากดนำเข้าต่อ');setCompleteRegistry(preview.registrySummary||null);setCompleteOrganization(preview.organizationSummary||null);setComplete({...preview.batch,visibility,status:'committed'});setPreview(null);setFile(null);await fetchStats();await fetchResults(applied,1);setPage(1);}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function showDetail(id:string):Promise<Row|null>{setError('');try{const d=await api('action=detail&id='+encodeURIComponent(id));setDetail(d);setEditing(false);return d.record;}catch(e){setError((e as Error).message);return null;}}
 function beginEdit(record:Row){const existingSchool=String(record.school||'');const isCentral=Boolean(findCentralSchool(existingSchool));const sourceProvince=String(record.source_province||'');const province=PROVINCES.includes(sourceProvince)?sourceProvince:isCentral?'กรุงเทพมหานคร':PROVINCES.includes(existingSchool)?existingSchool:'';setEditProvince(province);setAutoSchool(!isCentral&&!!province);setEditSchool(isCentral?existingSchool:province?'คณะจังหวัด'+province:existingSchool);setEditing(true);}
 async function openEdit(id:string){const record=await showDetail(id);if(record)beginEdit(record);}
 async function trashRecord(r:Row){const name=`${r.title||''}${r.first_name} ${r.last_name}`.trim();if(!confirm(toThai(`ยืนยันต้องการที่จะลบข้อมูลนี้หรือไม่?\n\n“${name}” จะย้ายไปถังขยะและกู้คืนได้ จนกว่าจะเลือกลบทิ้งถาวร`)))return;setBusy(true);setError('');try{await post({action:'trash-record',id:r.id,acknowledge:true});await Promise.all([fetchStats(),fetchResults(applied,page),fetchTrash(trashResult.page)]);if(detail?.record.id===r.id)setDetail(null);setNotice(`ย้าย “${name}” ไปถังขยะแล้ว`);}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function restoreRecord(r:Row){setBusy(true);setError('');try{await post({action:'restore-record',id:r.id,acknowledge:true});await Promise.all([fetchStats(),fetchResults(applied,page),fetchTrash(trashResult.page)]);setNotice(`กู้คืน “${r.title||''}${r.first_name} ${r.last_name}” แล้ว`);}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function purgeRecord(r:Row){const name=`${r.title||''}${r.first_name} ${r.last_name}`.trim();if(!confirm(toThai(`ยืนยันลบทิ้งถาวร “${name}” หรือไม่?\n\nข้อมูลรายชื่อนี้และประวัติจะถูกลบจากฐานข้อมูลถาวร ส่วนไฟล์ Excel ต้นฉบับยังอยู่ในชุดข้อมูล และกู้คืนรายชื่อนี้ไม่ได้`)))return;setBusy(true);setError('');try{await post({action:'purge-record',id:r.id,acknowledge:true});await Promise.all([fetchTrash(trashResult.page),fetchStats()]);setNotice(`ลบ “${name}” ออกจากระบบถาวรแล้ว`);}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function edit(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!detail)return;setBusy(true);try{const data=Object.fromEntries(new FormData(e.currentTarget));await post({...data,action:'edit',id:detail.record.id});await showDetail(detail.record.id);await fetchResults(applied,page);setNotice('บันทึกการแก้ไขและประวัติเรียบร้อยแล้ว');}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function changeBatch(b:Batch,action:string){if(action==='publish'&&!confirm(toThai('เผยแพร่รายชื่อในชุดนี้ให้ผู้ใช้ทั่วไปสืบค้นได้ โดยไม่เปิดไฟล์ต้นฉบับและหมายเหตุ?')))return;if(action==='archive'&&!confirm(toThai(`เก็บชุด ${b.filename} ออกจากผลสืบค้น? สามารถคืนได้ภายหลัง`)))return;setBusy(true);setError('');try{await post({action,id:b.id,acknowledge:true});await Promise.all([fetchBatches(),fetchStats(),fetchResults(applied,page)]);setNotice(action==='publish'?'เผยแพร่ชุดข้อมูลแล้ว':action==='unpublish'?'พักการเผยแพร่แล้ว':action==='archive'?'เก็บชุดข้อมูลออกจากการสืบค้นแล้ว':'คืนชุดข้อมูลเข้าสู่การสืบค้นแล้ว');}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function enrichRegistry(b:Batch,kind:'temple'|'organization'='temple'){setBusy(true);setError('');try{const organization=kind==='organization',d=await post({action:organization?'enrich-organization-registry':'enrich-registry',id:b.id,acknowledge:true});await Promise.all([fetchBatches(),fetchStats(),fetchResults(applied,page)]);if(!d.checkedRecords){setNotice('ไฟล์นี้ไม่มีรายชื่อ'+(organization?'ธรรมศึกษา':'นักธรรม')+'สำหรับตรวจเทียบ');return;}if(organization){const r=d.organizationSummary;setNotice(`ตรวจธรรมศึกษา ${num(d.checkedRecords)} รายชื่อ · ตรงทะเบียนองค์กร/สถานศึกษา ${num(r?.matched)} · เติมข้อมูล ${num(d.updatedRecords)} รายชื่อ (ตำบล ${num(r?.autoFilledSubdistrict)} · อำเภอ ${num(r?.autoFilledDistrict)} · จังหวัด ${num(r?.autoFilledProvince)}) · ชื่อซ้ำ ${num(r?.ambiguous)} · ที่อยู่ขัดแย้ง ${num(r?.locationMismatch)}`);}else{const r=d.registrySummary;setNotice(`ตรวจนักธรรม ${num(d.checkedRecords)} รายชื่อ · ตรงทะเบียนวัด ${num(r?.matched)} · เติมข้อมูล ${num(d.updatedRecords)} รายชื่อ (ตำบล ${num(r?.autoFilledSubdistrict)} · จังหวัด ${num(r?.autoFilledProvince)} · นิกาย ${num(r?.autoFilledSect)}) · ต้องตรวจต่อ ${num((r?.sectConflict||0)+(r?.ambiguous||0)+(r?.incomplete||0)+(r?.locationMismatch||0)+(r?.notFound||0))}`);}}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function deleteBatch(b:Batch){if(!confirm(toThai(`ลบชุด “${b.filename}” และข้อมูลที่เกี่ยวข้องอย่างถาวรหรือไม่?\n\nระบบจะลบรายชื่อที่บันทึกแล้ว ${num(b.inserted)} รายการ ไฟล์ Excel ต้นฉบับ และข้อมูลตรวจทาน การลบนี้ย้อนกลับไม่ได้`)))return;setBusy(true);setError('');try{const d=await post({action:'delete-batch',id:b.id,acknowledge:true});await Promise.all([fetchBatches(),fetchStats(),fetchResults(applied,page)]);if(preview?.batch.id===b.id)setPreview(null);if(complete?.id===b.id)setComplete(null);if(detail?.record.batch_id===b.id)setDetail(null);setNotice(d.storageCleaned===false?`ลบรายชื่อ ${num(d.deletedRecords)} รายการแล้ว แต่ลบไฟล์ต้นฉบับจากที่เก็บไม่สำเร็จ`: `ลบชุดข้อมูลและรายชื่อ ${num(d.deletedRecords)} รายการออกจากระบบแล้ว`);}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 const regionChoices=Array.from(new Set([...REGIONS,...knownRegions]));
 const nav=[{key:'search' as Tab,label:'สืบค้นรายชื่อ',icon:Search},{key:'upload' as Tab,label:'นำเข้าข้อมูล Excel',icon:Upload},{key:'sects' as Tab,label:'ตรวจนิกายตามวัด / พื้นที่',icon:ShieldCheck},{key:'temples' as Tab,label:'ทะเบียนอ้างอิง',icon:Database},{key:'statistics' as Tab,label:'ทะเบียนสถิติผลสอบ',icon:ChartColumn},{key:'batches' as Tab,label:'ชุดข้อมูลผู้ดูแล',icon:Layers},{key:'trash' as Tab,label:'ถังขยะรายชื่อ',icon:Trash2},{key:'help' as Tab,label:'คู่มือการใช้งาน',icon:CircleHelp}].filter(n=>role!=='viewer'||['search','statistics','batches','help'].includes(n.key));
 return <ThaiNumerals><div className="app-shell"><aside className="sidebar"><a className="brand" href="/"><span className="brand-symbol"><BookOpen size={28}/></span><span><strong>ธรรมทะเบียน</strong><small>DHAMMA REGISTRY</small></span></a><div className="workspace-label">พื้นที่ทำงาน <span>ภายใน</span></div><nav aria-label="เมนูหลัก">{nav.map(n=><button key={n.key} aria-current={tab===n.key?'page':undefined} className={tab===n.key?'nav-item active':'nav-item'} onClick={()=>navigate(n.key)} disabled={busy}><n.icon size={20}/>{n.label}{tab===n.key?<ChevronRight size={16}/>:null}</button>)}</nav>{role==='admin'?<nav aria-label="การตรวจสอบ"><a className="nav-item" href="/admin/audit"><History size={20}/>ประวัติการใช้งานและแก้ไข</a><a className="nav-item" href="/admin/staff"><Users size={20}/>มอบหมายสิทธิ์ผู้ใช้</a></nav>:null}<div className="sidebar-tip"><ShieldCheck size={24}/><strong>พื้นที่ผู้ดูแลระบบ</strong><p>ผู้ใช้ทั่วไปเห็นเฉพาะชุดที่เผยแพร่ ไฟล์ต้นฉบับและหมายเหตุเข้าถึงได้เฉพาะผู้ดูแล</p></div><div className="profile"><span className="avatar">{user.name?user.name.charAt(0).toUpperCase():'ธ'}</span><div><strong>{user.name||'บัญชีผู้ใช้งาน'}</strong><small>พื้นที่จัดการข้อมูล</small></div><form method="post" action="/api/session"><button aria-label="ออกจากระบบ"><LogOut size={18}/></button></form></div></aside><div className="main-shell"><header className="topbar"><div className="breadcrumb">ระบบทะเบียนผู้สอบได้ <ChevronRight size={14}/><strong>{nav.find(n=>n.key===tab)?.label}</strong></div><span className="private-badge"><span/>ผู้ดูแลระบบ</span></header><main id="main-content"><div className="admin-banner"><span><ShieldCheck size={16}/>พื้นที่นำเข้าและจัดการสำหรับผู้ดูแลระบบ</span><a className="text-button" href="/">เปิดหน้าสืบค้นทั่วไป<ArrowUpRight size={14}/></a></div>
 {tab!=='search'?<button className="back-button" onClick={()=>navigate('search')} disabled={busy}><ArrowLeft size={16}/>กลับหน้าสืบค้น</button>:null}
 {error?<div className="alert error" role="alert"><AlertTriangle size={19}/><div>{error}{error==='กรุณาเข้าสู่ระบบ'?<a href="/signin-with-chatgpt?return_to=/" target="_top"> เข้าสู่ระบบด้วย ChatGPT</a>:null}</div><button onClick={()=>setError('')} aria-label="ปิดข้อความ"><X size={16}/></button></div>:null}
 {notice?<div className="alert success" role="status"><Check size={19}/>{notice}<button onClick={()=>setNotice('')} aria-label="ปิดข้อความ"><X size={16}/></button></div>:null}
 {tab==='temples'?<ProvinceDirectory/>:null}<OrganizationRegistry active={tab==='temples'} onStatus={setOrganizationStatus} onComplete={()=>{void fetchResults(applied,page);void fetchStats().catch(e=>setError(e.message));}}/><TempleRegistry active={tab==='temples'} onStatus={setRegistryStatus}/>{organizationStatus&&(!organizationStatus.ready||organizationStatus.backfillStatus!=='done')&&tab!=='temples'?<div className="info-line banner"><Database size={18}/><p>{organizationStatus.ready?'กำลังตรวจที่อยู่องค์กร/สถานศึกษาในข้อมูลเดิม':'กำลังนำเข้าทะเบียนองค์กรและสถานศึกษา'} · {num(organizationStatus.loaded)} / {num(organizationStatus.expected)} แถว</p><button className="text-button" onClick={()=>navigate('temples')}>ดูความคืบหน้า</button></div>:null}{registryStatus&&!registryStatus.ready&&tab!=='temples'?<div className="info-line banner"><Database size={18}/><p>กำลังติดตั้งทะเบียนวัดอ้างอิง {num(registryStatus.loaded)} / {num(registryStatus.expected)} รายการ</p><button className="text-button" onClick={()=>navigate('temples')}>ดูความคืบหน้า</button></div>:null}
 {tab==='search'?<><section className="page-heading"><div><div className="eyebrow">บันทึกความสำเร็จ · เชื่อมโยงการศึกษา</div><h1>สืบค้นรายชื่อผู้สอบได้</h1><p>นักธรรมและธรรมศึกษา · ทุกภาค ทุกจังหวัด · มหานิกายและธรรมยุต</p></div><button className="button primary" onClick={()=>{setPreview(null);setComplete(null);navigate('upload');}}><Upload size={18}/>นำเข้า Excel</button></section><section className="hero-card"><div className="hero-content"><span className="gold-label"><BookOpen size={16}/>ทะเบียนผลสอบ</span><h2>ค้นพบข้อมูลได้ง่าย<br/>จากทะเบียนเดียวกัน</h2><p>ค้นหาด้วยชื่อ ฉายา หรือสังกัด<br/>พร้อมกรองภาค นิกาย จังหวัด และปี พ.ศ.</p><span className="hero-foot"><ShieldCheck size={15}/>เก็บที่มา ตรวจทานได้ทุกชุดข้อมูล</span></div><div className="book-art" aria-hidden="true"><div className="art-ring ring-one"/><div className="art-ring ring-two"/><svg viewBox="0 0 300 230"><path d="M47 57Q99 43 150 72Q200 43 253 57L261 182Q205 168 150 198Q94 168 39 182Z" fill="#b59252" opacity=".35"/><path d="M48 46Q103 33 150 62Q199 33 252 46L252 173Q202 157 150 186Q98 157 48 173Z" fill="#e6d1a6"/><path d="M57 38Q104 28 147 58V175Q102 150 57 164Z" fill="#f8edd4"/><path d="M155 58Q200 28 243 38V164Q200 150 155 175Z" fill="#e8d5af"/><g stroke="#bfa474" strokeWidth="2" opacity=".6"><path d="M72 65Q104 64 131 79M72 85Q104 84 131 99M72 105Q104 104 131 119M72 125Q104 124 131 139M171 79Q202 64 229 65M171 99Q202 84 229 85M171 119Q202 104 229 105M171 139Q202 124 229 125"/></g><path d="M198 37v70l13-13 12 6V34" fill="#a3733f"/><path d="M149 184v14" stroke="#b59252" strokeWidth="2"/></svg><span className="art-spark s1">✦</span><span className="art-spark s2">✧</span></div><div className="hero-side"><span>ทะเบียนของผู้ดูแล</span><strong>{num(stats?.total)}</strong><span>รายชื่อ</span><div className="hero-date"><span className="status-dot"/>{latest?'อัปเดต '+date(latest):'พร้อมรับข้อมูลชุดแรก'}</div></div></section><section className="stat-grid" aria-label="ภาพรวมข้อมูล"><Stat icon={<Users size={21}/>} label="นักธรรม" value={num(stats?.monastic)} sub="ตรี · โท · เอก"/><Stat icon={<BookOpen size={21}/>} label="ธรรมศึกษา" value={num(stats?.lay)} sub="ตรี · โท · เอก"/><Stat icon={<MapPin size={21}/>} label="จังหวัดที่มีข้อมูล" value={num(stats?.provinces)} sub="จาก 77 จังหวัด"/><Stat icon={<CalendarDays size={21}/>} label="ปีการสอบ" value={num(stats?.years)} sub="ปี พ.ศ. ในระบบ"/></section><div className="scope-overview"><span>ภาคที่มีข้อมูล <b>{num(stats?.regions)}</b></span><span>มหานิกาย <b>{num(stats?.maha)}</b></span><span>ธรรมยุต <b>{num(stats?.dhammayut)}</b></span><span>ไม่ระบุนิกาย <b>{num(stats?.unknown_sect)}</b></span></div><section className="card search-card"><div className="section-heading"><h2><Search size={20}/>ค้นหาทะเบียน</h2><span>ระบุข้อมูลอย่างน้อยหนึ่งช่อง หรือดูทั้งหมด</span></div><form onSubmit={search}><label className="search-input"><Search size={21}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="ค้นหาชื่อ นามสกุล ฉายา วัด หรือสำนักเรียน" aria-label="คำค้นหา" maxLength={150}/>{query?<button type="button" onClick={()=>setQuery('')} aria-label="ล้างคำค้น"><X size={17}/></button>:null}<kbd>ค้นหา</kbd></label><div className="filter-grid"><Select label="จังหวัดสนามสอบ" value={province} onChange={setProvince} options={PROVINCES}/><Select label="ปี พ.ศ." value={year} onChange={setYear} options={years.map(String)}/><Select label="ประเภทการสอบ" value={category} onChange={setCategory} options={['นักธรรม','ธรรมศึกษา']}/><Select label="ระดับชั้น" value={level} onChange={setLevel} options={['ตรี','โท','เอก']}/><Select label="เรียงเลขที่ ปกศ." value={sort} onChange={setSort} options={['certificate_asc','certificate_desc']} /><Select label="ภาค" value={region} onChange={setRegion} options={[...regionChoices,'ไม่ระบุ']}/><Select label="นิกาย" value={sect} onChange={v=>{setSect(v);setSchoolFilter('');}} options={[...SECTS,'ไม่ระบุ']}/><Select label="พื้นที่การศึกษา" value={jurisdiction} onChange={setJurisdiction} options={['ส่วนกลาง','ส่วนภูมิภาค']}/><Select label="ชนิดสำนักเรียนส่วนกลาง" value={kindFilter} onChange={v=>{setKindFilter(v);setSchoolFilter('');}} options={CENTRAL_SCHOOL_KINDS}/><Select label="ชื่อสำนักเรียนส่วนกลาง" value={schoolFilter} onChange={v=>{setSchoolFilter(v);const s=findCentralSchool(v);if(s){setJurisdiction('ส่วนกลาง');setSect(s.sect);setProvince('กรุงเทพมหานคร');setRegion('');setKindFilter(s.kind);}}} options={CENTRAL_SCHOOLS.filter(s=>(!sect||s.sect===sect)&&(!kindFilter||s.kind===kindFilter)).map(s=>s.name)}/><button className="button primary search-submit" type="submit"><Search size={17}/>สืบค้น</button></div></form></section><section className="card result-card"><div className="result-heading"><div><h2>ผลการสืบค้น <span className="count-badge">{num(results.total)}</span></h2><p>{applied.size?'ตามเงื่อนไขที่เลือก':'รายชื่อทั้งหมดในทะเบียนของคุณ'}</p></div><div className="button-group">{applied.size?<button className="text-button" onClick={reset}>ล้างตัวกรอง</button>:null}<a className={`button secondary small ${results.total===0?'disabled':''}`} href={'/api/passlist?action=export&'+applied.toString()} aria-disabled={results.total===0} onClick={e=>{if(!results.total)e.preventDefault();}}><Download size={16}/>ส่งออก CSV</a></div></div>{loading?<div className="empty"><Loader2 className="spin" size={30}/><p>กำลังค้นหาข้อมูล…</p></div>:results.items.length?<><ExamResultsTable rows={results.items} onDetail={r=>showDetail(r.id)} onEdit={r=>openEdit(r.id)} onTrash={trashRecord} busy={busy}/><div className="pagination"><div className="pagination-summary"><PageSizeSelect value={pageSize} onChange={size=>{setPageSize(size);setPage(1);}} disabled={loading||busy} sizes={ADMIN_RECORD_PAGE_SIZES}/><span>แสดง {(results.page-1)*pageSize+1}–{Math.min(results.page*pageSize,results.total)} จาก {num(results.total)} รายชื่อ</span></div><Pagination page={results.page} pages={results.pages} onChange={setPage} disabled={loading}/></div></>:<div className="empty"><span className="empty-symbol">{stats?.total?<Search size={30}/>:<FolderOpen size={32}/>}</span><h3>{stats?.total?'ไม่พบรายชื่อตามเงื่อนไข':'เริ่มต้นทะเบียนของคุณ'}</h3><p>{stats?.total?'ลองตรวจคำสะกด หรือปรับจังหวัด ปี และระดับชั้น':'นำเข้ารายชื่อจากไฟล์ Excel เพื่อเริ่มค้นหาข้อมูล'}</p><button className="button secondary" onClick={()=>stats?.total?reset():navigate('upload')}>{stats?.total?'ล้างตัวกรอง':<><Upload size={17}/>นำเข้าข้อมูลชุดแรก</>}</button></div>}</section></>:null}
 {tab==='upload'?<><section className="page-heading"><div><div className="eyebrow">จัดการข้อมูล / นำเข้า</div><h1>นำเข้าข้อมูลจาก Excel</h1><p>ตรวจข้อมูลและจัดกลุ่มอัตโนมัติ พร้อมนำเข้าและเผยแพร่เมื่อผ่านเกณฑ์</p></div><a className="button secondary" href="/api/passlist?action=template"><Download size={18}/>ดาวน์โหลดแม่แบบ</a></section><div className="steps">{['เลือกไฟล์และปีการสอบ','ตรวจทานข้อมูล','นำเข้าเรียบร้อย'].map((s,i)=><div key={s} className={(complete?2:preview?1:0)===i?'current':(complete?2:preview?1:0)>i?'past':''}><span>{(complete?2:preview?1:0)>i?<Check size={16}/>:i+1}</span>{s}{i<2?<ChevronRight size={17}/>:null}</div>)}</div><div className="info-line banner"><Database size={19}/><p>{registryStatus?.ready?`ระบบใช้ทะเบียนวัดอ้างอิง ${num(registryStatus.loaded)} รายการ เพื่อตรวจชื่อและพื้นที่ในไฟล์`:`ทะเบียนวัดอ้างอิง ${registryStatus?'กำลังติดตั้ง':'กำลังตรวจสอบสถานะ'} ${num(registryStatus?.loaded)} / ${num(registryStatus?.expected)} รายการ กรุณารอให้เสร็จก่อนอัปโหลดรายชื่อ`}</p></div>{complete?<section className="card complete"><span className="complete-check"><Check size={38}/></span><h2>นำเข้ารายชื่อเรียบร้อยแล้ว</h2><p>{scopeLabel(complete)} · พ.ศ. {batchYear(complete)||'หลายปี / อ่านจากไฟล์'}</p><OrganizationSummaryBox value={completeOrganization}/><RegistrySummaryBox value={completeRegistry} downloadId={complete.id}/><strong>{num(complete.valid)} <span>{complete.visibility==='published'?'รายชื่อเผยแพร่แล้ว':'รายชื่อเก็บภายใน รอตรวจทาน'}</span></strong>{complete.total>complete.valid?<p>แยกแถวที่มีข้อผิดพลาด {num(complete.total-complete.valid)} แถวไว้ในรายงานตรวจทาน</p>:null}<div className="button-group">{complete.visibility!=='published'?<button className="button primary" onClick={()=>{navigate('sects');setReviewBatch(complete.id);}}>กำหนดนิกายตามวัด / พื้นที่<ShieldCheck size={17}/></button>:null}{complete.visibility==='published'?<a className="button primary" href="/">เปิดหน้าสืบค้นทั่วไป<ArrowUpRight size={17}/></a>:null}<button className="button secondary" onClick={()=>{setApplied(new URLSearchParams({...complete.province!=='อ่านจากไฟล์'?{province:complete.province}:{},...batchYear(complete)?{year:batchYear(complete)}:{}}));setProvince(complete.province==='อ่านจากไฟล์'?'':complete.province);setQuery('');setCategory('');setLevel('');setRegion('');setSect('');setYear(batchYear(complete));setPage(1);navigate('search');}}>สืบค้นชุดข้อมูลนี้<ArrowUpRight size={17}/></button><button className="button secondary" onClick={()=>{setComplete(null);setFile(null);}}>นำเข้าชุดถัดไป</button></div></section>:preview?<><>{preview.holds?.length?<div className="auto-holds"><strong>{deferSect?'ข้อสังเกตสำหรับตรวจทานภายหลัง':'พักการนำเข้าอัตโนมัติ: ต้องตรวจทาน'}</strong><ul>{preview.holds.slice(0,15).map(h=><li key={h}>{h}</li>)}</ul></div>:null}</><section className="card preview-summary"><div className="section-heading"><div><span className="eyebrow">พร้อมให้ตรวจทาน</span><h2>{preview.batch.filename}</h2><p>{scopeLabel(preview.batch)} · พ.ศ. {batchYear(preview.batch)||'หลายปี / อ่านจากไฟล์'}</p></div><button className="button secondary small" disabled={busy} onClick={()=>{setPreview(null);setFile(null);}}>เลือกไฟล์ใหม่</button></div><div className="review-stats"><div><span>แถวรายชื่อทั้งหมด</span><strong>{num(preview.batch.total)}</strong></div><div><span>ผ่านเกณฑ์นำเข้า</span><strong className="green-text">{num(preview.batch.valid)}</strong></div><div><span>มีข้อผิดพลาด</span><strong className="red-text">{num(preview.batch.total-preview.batch.valid)}</strong></div><div><span>แถวที่ต้องตรวจทาน</span><strong className="gold-text">{num(preview.issueTotal)}</strong></div></div><OrganizationSummaryBox value={preview.organizationSummary}/><RegistrySummaryBox value={preview.registrySummary} downloadId={preview.batch.id}/><div className="group-chips">{preview.groups.map((g,i)=><span className="tag" key={i}>{g.region||'ไม่ระบุภาค'} · {g.province||preview.batch.province} · {g.sect||'ไม่ระบุนิกาย'} · {g.category} {g.level} · {g.school||'ไม่ระบุสำนักเรียน'} <b>{num(g.count)}</b></span>)}</div>{preview.reconciliation?<div className={preview.reconciliation.matches===false?'reconcile-box bad':'reconcile-box'}>ยอดสอบได้ที่ประกาศในไฟล์: {preview.reconciliation.declared===null?'ไม่ระบุ':num(preview.reconciliation.declared)} · รายชื่อผ่านเกณฑ์: {num(preview.reconciliation.found)} {preview.reconciliation.matches===false?'— ยอดไม่ตรง ต้องตรวจทาน':''}</div>:null}<p className="muted">ข้ามหัวตาราง สถิติ และแถวประกอบ {num(preview.ignored)} แถว · ยังไม่บันทึกเข้าสู่ผลสืบค้น</p></section><section className="card"><div className="result-heading"><div className="segmented"><button onClick={()=>{setIssueView(true);void pagePreview(1);}} disabled={busy} aria-pressed={issueView}>รายการต้องตรวจทาน ({num(preview.issueTotal)})</button><button onClick={()=>{setIssueView(false);void pagePreview(1);}} disabled={busy} aria-pressed={!issueView}>รายชื่อทั้งหมด</button></div><a className="text-button" href={'/api/passlist?action=issues&id='+preview.batch.id}><Download size={16}/>รายงานทั้งหมด</a></div><div className="table-wrap preview-table"><table><thead><tr><th>ชีต / แถว</th><th>ชื่อ–นามสกุล</th><th>ประเภท / ชั้น / นิกาย</th><th>ภาค / จังหวัด</th><th>ผลตรวจสอบ</th></tr></thead><tbody>{(issueView?preview.issues:preview.records).map(r=><tr key={r.id}><td><small>{r.sheet}</small>แถว {r.row}</td><td>{r.title}{r.firstName||'(ไม่มีชื่อ)'} {r.lastName}<small>{r.dharmaName}</small></td><td>{r.category} {r.level}<small>{r.sect||'ไม่ระบุนิกาย'}</small></td><td>{r.province||preview.batch.province}<small>{r.region||r.jurisdiction||'ไม่ระบุภาค'} · {r.school}</small></td><td>{r.errors.length?<span className="issue-error">{r.errors.join(' · ')}</span>:null}{r.warnings.length?<small className="gold-text">{r.warnings.join(' · ')}</small>:null}{!r.errors.length&&!r.warnings.length?<span className="green-text">ผ่านการตรวจสอบ</span>:null}</td></tr>)}</tbody></table>{issueView&&!preview.issueTotal?<div className="empty compact"><Check size={25}/><p>ไม่พบรายการผิดปกติจากการตรวจอัตโนมัติ</p></div>:null}</div><div className="pagination"><div className="pagination-summary"><PageSizeSelect value={previewSize} onChange={size=>{setPreviewSize(size);void pagePreview(1,size);}} disabled={busy}/><span>{num(issueView?preview.issueTotal:preview.recordsTotal)} รายการ</span></div><Pagination page={issueView?preview.issuePage:preview.recordPage} pages={issueView?preview.issuePages:preview.recordPages} onChange={p=>{void pagePreview(p);}} disabled={busy}/></div></section><section className="card confirmation"><div className="info-line"><Info size={20}/><p>รายการที่มีข้อสังเกต เช่น นามสกุลไม่ครบ เลขลำดับทศนิยม หรือข้อมูลหลักซ้ำ <strong>ยังนำเข้าได้และจะไม่ถูกลบอัตโนมัติ</strong> โปรดตรวจให้ตรงกับบัญชีต้นฉบับ</p></div>{preview.batch.total>preview.batch.valid?<label className="check-line"><input type="checkbox" checked={exclude} onChange={e=>setExclude(e.target.checked)} disabled={busy}/>ยืนยันแยก {num(preview.batch.total-preview.batch.valid)} แถวที่มีข้อผิดพลาดออกจากการนำเข้าครั้งนี้ (เก็บต้นฉบับและรายงานไว้)</label>:null}<label className="check-line"><input type="checkbox" checked={deferSect} onChange={e=>{setDeferSect(e.target.checked);loadPreview(preview.batch.id,e.target.checked).catch(e=>setError(e.message));}} disabled={busy}/>นำเข้าได้แม้ไม่ระบุนิกาย กำหนดนิกายในหลังบ้านภายหลัง (ใช้ได้กับไฟล์รวมสองนิกาย)</label><label className="check-line"><input type="checkbox" checked={publishAfter} onChange={e=>setPublishAfter(e.target.checked)} disabled={busy}/>เผยแพร่ให้ผู้ใช้ทั่วไปค้นด้วยชื่อและนามสกุลหลังนำเข้า (นิกายระบุภายหลังได้)</label><label className="check-line"><input type="checkbox" checked={ack} onChange={e=>setAck(e.target.checked)} disabled={busy}/>{deferSect?'ฉันตรวจข้อมูลหลักและข้อสังเกตแล้ว มีสิทธิ์นำเข้าข้อมูล และจะตรวจนิกายภายหลัง':'ฉันตรวจภาค จังหวัด นิกาย ชั้น ปี พ.ศ. และรายการต้องตรวจทานแล้ว และมีสิทธิ์นำเข้าข้อมูลชุดนี้'}</label>{busy||progress>0?<div className="progress-area"><progress value={progress} max={100}/><span>{progress}% · {busy?'กำลังนำเข้า กรุณาเปิดหน้านี้ไว้':'สามารถกดนำเข้าต่อได้'}</span></div>:null}<div className="confirmation-footer"><span><ShieldCheck size={16}/>ต้นฉบับและหมายเหตุเฉพาะผู้ดูแล</span><button className="button primary" disabled={busy||!ack||!preview.batch.valid||(preview.batch.total>preview.batch.valid&&!exclude)} onClick={commit}>{busy?<Loader2 className="spin" size={18}/>:<FileCheck2 size={18}/>} {busy?'กำลังบันทึก…':preview.batch.inserted?'นำเข้าต่อ':'ยืนยันนำเข้า '+num(preview.batch.valid)+' รายชื่อ'}</button></div></section></>:<div className="upload-layout"><form className="card upload-form" onSubmit={upload}><div className="section-heading"><h2><span className="number-label">01</span>ระบุชุดข้อมูล</h2><span>อ่านประเภท ชั้น จังหวัด ภาค และปีจากไฟล์</span></div><div className="two-col"><Select label="จังหวัดสนามสอบ" value={upProvince} onChange={setUpProvince} options={PROVINCES} placeholder="อ่านจากไฟล์ (หลายจังหวัดได้)"/><label className="field"><span>ปีการสอบ พ.ศ. (ถ้าไฟล์ไม่ระบุ)</span><input type="text" inputMode="numeric" value={upYear} onChange={e=>setUpYear(toArabic(e.target.value))} min="2400" max={new Date().getFullYear()+544} placeholder="อ่านจากไฟล์อัตโนมัติ"/></label></div><label className="check-line"><input type="checkbox" checked={deferSect} onChange={e=>{setDeferSect(e.target.checked);}}/>นำเข้าไว้ก่อน กำหนดนิกายภายหลัง — เหมาะกับไฟล์ที่มีทั้งสองนิกาย</label><p className="scope-hint">ไม่ต้องเลือกนิกายเดียวให้ทั้งไฟล์ สามารถกดเผยแพร่ได้แม้ยังไม่ระบุนิกาย และตรวจเพิ่มเติมที่เมนู “ตรวจนิกายตามวัด / พื้นที่”</p><div className="two-col scope-defaults"><label className="field"><span>ภาคเริ่มต้น (ใช้เมื่อไฟล์ไม่ระบุ)</span><input value={upRegion} onChange={e=>setUpRegion(e.target.value)} list="region-options" placeholder="อ่านจากไฟล์ เช่น ภาค 1 หรือ ภาค 4-5-6-7" maxLength={100}/></label>{deferSect?<div className="scope-hint">นิกาย: อ่านค่าที่ชัดเจนจากแต่ละแถว ส่วนที่ไม่ชัดเจนจะรอแอดมินเลือกภายหลัง</div>:<Select label="นิกายเริ่มต้น (เฉพาะไฟล์นิกายเดียว)" value={upSect} onChange={setUpSect} options={SECTS} placeholder="อ่านจากไฟล์ / ไม่ระบุ"/>}</div><div className="two-col scope-defaults"><Select label="พื้นที่การศึกษาเริ่มต้น" value={upJurisdiction} onChange={setUpJurisdiction} options={['ส่วนกลาง','ส่วนภูมิภาค']} placeholder="อ่านจากไฟล์"/><label className="field"><span>สำนักเรียนส่วนกลางเริ่มต้น</span><input value={upSchool} onChange={e=>{setUpSchool(e.target.value);if(findCentralSchool(e.target.value)){setUpJurisdiction('ส่วนกลาง');setUpProvince('กรุงเทพมหานคร');}}} list="central-school-options" placeholder="อ่านจากหัวข้อ หรือเลือกชื่อในทะเบียน" maxLength={500}/></label></div><label className="check-line"><input type="checkbox" checked={useSourceProvince} onChange={e=>setUseSourceProvince(e.target.checked)}/>ฉันยืนยันว่าคอลัมน์ “จังหวัด” ในไฟล์นี้เป็นจังหวัดสนามสอบ ให้ใช้เมื่อไม่มีหัวข้อหรือคอลัมน์จังหวัดสนามสอบ</label><p className="scope-hint">ไฟล์รวมหลายจังหวัดให้เลือก “อ่านจากไฟล์” ระบบอ่านจังหวัดสนามสอบ ภาค และนิกายจากแต่ละแถว หัวข้อ หรือชื่อชีต และเทียบชื่อวัดกับทะเบียนวัดที่บันทึกในระบบ เมื่อชื่อและพื้นที่ตรงกันเพียงรายการเดียว จะเติมตำบล จังหวัดสังกัด และนิกายให้โดยอัตโนมัติ ส่วนชื่อซ้ำหรือข้อมูลขัดแย้งจะไม่เดาและให้ตรวจทาน</p><details className="defaults"><summary>ไฟล์ไม่มีคอลัมน์ประเภทหรือระดับชั้น</summary><p>ระบุค่าเริ่มต้นเฉพาะไฟล์ที่ยังไม่มีข้อมูลนี้ ไฟล์บัญชีเดิมจะอ่านประเภทและชั้นจากหัวข้อแต่ละกลุ่ม</p><div className="two-col"><Select label="ประเภทเริ่มต้น" value={upCategory} onChange={setUpCategory} options={['นักธรรม','ธรรมศึกษา']} placeholder="อ่านจากไฟล์อัตโนมัติ"/><Select label="ระดับชั้นเริ่มต้น" value={upLevel} onChange={setUpLevel} options={['ตรี','โท','เอก']} placeholder="อ่านจากไฟล์อัตโนมัติ"/></div></details><CentralDirectory action="ใช้เป็นค่าเริ่มต้น" onSelect={s=>{setUpSchool(s.name);setUpJurisdiction('ส่วนกลาง');setUpProvince('กรุงเทพมหานคร');}}/><h2 className="upload-title"><span className="number-label">02</span>เลือกไฟล์ Excel</h2><label className={'dropzone '+(drag?'dragging':'')} onDragOver={e=>{e.preventDefault();setDrag(true);}} onDragLeave={()=>setDrag(false)} onDrop={e=>{e.preventDefault();setDrag(false);setFile(e.dataTransfer.files[0]||null);}}><input type="file" accept=".xlsx" onChange={e=>setFile(e.target.files?.[0]||null)} disabled={busy}/><span className="file-symbol"><FileSpreadsheet size={31}/></span><strong>{file?file.name:'ลากไฟล์มาวาง หรือคลิกเพื่อเลือก'}</strong><span>{file?num(Math.ceil(file.size/1024))+' KB':'Excel (.xlsx) · สูงสุด 10 MB / 200,000 รายชื่อ'}</span><span className="button secondary small">{file?'เปลี่ยนไฟล์':'เลือกไฟล์จากเครื่อง'}</span></label><div className="auto-options"><label className="check-line"><input type="checkbox" checked={automatic} onChange={e=>setAutomatic(e.target.checked)} disabled={busy}/>{deferSect?'ตรวจ จัดกลุ่ม และบันทึกภายในอัตโนมัติ':'ตรวจ จัดกลุ่ม นำเข้า และเผยแพร่อัตโนมัติเมื่อข้อมูลผ่านเกณฑ์'}</label><p>{deferSect?'นำเข้ารายชื่อที่ข้อมูลหลักครบได้แม้นิกายยังไม่ระบุ โดยไม่เผยแพร่ต่อสาธารณะ หากชื่อ ประเภท ชั้น หรือปีไม่ถูกต้อง จะให้ตรวจและยืนยันแยกแถวก่อน':'ข้อมูลครบ ไม่มีข้อผิดพลาดหรือคำเตือน และยอดสถิติตรงกันจึงบันทึกและเผยแพร่ หากข้อมูลไม่ครบจะพักไว้ให้ตรวจทาน'}</p></div><div className="upload-footer"><p><ShieldCheck size={15}/>ตรวจสอบบนเซิร์ฟเวอร์</p><button className="button primary" type="submit" disabled={busy||!file||!organizationStatus?.ready}>{busy?<Loader2 className="spin" size={18}/>:<Search size={18}/>} {busy?'กำลังตรวจและดำเนินการ…':automatic?'เริ่มนำเข้าอัตโนมัติ':'ตรวจสอบข้อมูล'}{!busy?<ChevronRight size={17}/>:null}</button></div></form><aside className="upload-help"><div className="card"><span className="help-icon"><FileSpreadsheet size={24}/></span><h3>เตรียมไฟล์ให้พร้อม</h3><ol><li>เลือกปีการสอบให้ตรงต้นฉบับ ถ้าไฟล์มีหลายจังหวัดให้เลือกอ่านจังหวัดจากไฟล์</li><li>ใช้แม่แบบ หรือไฟล์บัญชีเดิมที่มีหัวคอลัมน์ ชื่อ และ นามสกุล</li><li>ตรวจยอดแยกภาค จังหวัด นิกาย และชั้น รวมถึงรายการผิดปกติ ก่อนยืนยันนำเข้า</li></ol><a className="text-button" href="/api/passlist?action=template">ดาวน์โหลดแม่แบบ .xlsx<ArrowUpRight size={16}/></a></div><div className="subtle-note"><Info size={19}/><p>รองรับทุกจังหวัด นักธรรม/ธรรมศึกษา ตรี–โท–เอก ทั้งมหานิกายและธรรมยุต รวมหลายกลุ่ม หลายชีต หัวตารางซ้ำ และเลขไทย</p></div><div className="subtle-note"><Archive size={19}/><p>ไฟล์ .xls แบบเก่า ให้เปิดด้วย Excel แล้วบันทึกเป็น .xlsx ก่อนอัปโหลด</p></div></aside></div>}</>:null}
 {tab==='statistics'?<StatisticsRegistry/>:null}
 {tab==='sects'?<SectReview key={reviewBatch} batchId={reviewBatch} onSaved={()=>{fetchStats().catch(e=>setError(e.message));fetchResults(applied,page);}}/>:null}
 {tab==='batches'?<><section className="page-heading"><div><div className="eyebrow">ข้อมูลและประวัติ</div><h1>ชุดข้อมูลผู้ดูแล</h1><p>ตรวจสอบที่มา ทำรายการต่อ และจัดการชุดข้อมูลที่นำเข้า</p></div><button className="button primary" onClick={()=>{setPreview(null);setComplete(null);navigate('upload');}}><Upload size={18}/>นำเข้าชุดใหม่</button></section><div className="info-line banner"><ShieldCheck size={20}/><p>เลือกจำนวนชุดข้อมูลต่อหน้าได้ด้านล่าง การเก็บชุดข้อมูลออกจะซ่อนรายชื่อจากการสืบค้นและคืนได้ภายหลัง ส่วนปุ่มถังขยะจะลบข้อมูลและไฟล์ต้นฉบับถาวร</p></div><section className="card">{batchList.length?<><div className="table-wrap"><table><thead><tr><th>ไฟล์ต้นฉบับ</th><th>จังหวัด / ปี พ.ศ.</th><th>จำนวน</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody>{batchList.map(b=><tr key={b.id}><td><span className="filename"><FileSpreadsheet size={18}/>{b.filename}</span><small>{b.age_status==='done'?`ตรวจอายุจากต้นฉบับแล้ว · เติม ${num(b.age_updated)} รายชื่อ`:b.age_status==='error'?`ตรวจอายุไม่ได้: ${b.age_error}`:'กำลังตรวจข้อมูลอายุจากต้นฉบับ'}</small><small>{b.vassa_status==='done'?`ตรวจพรรษาจากต้นฉบับแล้ว · เติม ${num(b.vassa_updated)} รายชื่อ`:b.vassa_status==='error'?`ตรวจพรรษาไม่ได้: ${b.vassa_error}`:'กำลังตรวจข้อมูลพรรษาจากต้นฉบับ'}</small><small>{date(b.created_at)}</small></td><td>{scopeLabel(b)}<small>พ.ศ. {batchYear(b)||'หลายปี / อ่านจากไฟล์'}</small></td><td>{num(b.status==='committed'||b.status==='archived'?b.valid:b.total)}<small>{b.issues?num(b.issues)+' แถวตรวจทาน':'ไม่มีข้อสังเกต'}</small></td><td><span className={'tag '+(b.status==='committed'?'green':b.status==='archived'?'':'sand')}>{statusLabel[b.status]}</span><small>{b.visibility==='published'?'เผยแพร่แล้ว':'ยังไม่เผยแพร่ · ประชาชนยังค้นไม่พบ'}</small></td><td><div className="row-actions batch-actions">{b.status==='committed'?<><button className="button secondary small" disabled={busy||!registryStatus?.ready} title="เทียบทะเบียนวัดเฉพาะรายชื่อนักธรรมในไฟล์นี้" onClick={()=>enrichRegistry(b,'temple')}>เทียบ/เติมทะเบียนวัด (นักธรรม)</button><button className="button secondary small" disabled={busy||!organizationStatus?.ready} title="เทียบทะเบียนองค์กรหรือสถานศึกษาเฉพาะรายชื่อธรรมศึกษาในไฟล์นี้" onClick={()=>enrichRegistry(b,'organization')}>เทียบ/เติมทะเบียนองค์กร/สถานศึกษา (ธรรมศึกษา)</button></>:null}{b.status==='committed'?<button className="button secondary small" onClick={()=>{navigate('sects');setReviewBatch(b.id);}}>ตรวจนิกาย</button>:null}{b.status==='committed'?<button className="button secondary small" disabled={busy} onClick={()=>changeBatch(b,b.visibility==='published'?'unpublish':'publish')}>{b.visibility==='published'?'พักเผยแพร่':'เผยแพร่'}</button>:null}<a className="button secondary small" href={'/api/passlist?action=thai-source&id='+b.id} title="ดาวน์โหลดสำเนาค่าข้อมูลใน Excel เป็นเลขไทย"><Download size={16}/>Excel เลขไทย</a><a className="icon-button" href={'/api/passlist?action=source&id='+b.id} aria-label="ดาวน์โหลดต้นฉบับ" title="ดาวน์โหลดต้นฉบับ"><Download size={17}/></a><a className="icon-button" href={'/api/passlist?action=issues&id='+b.id} aria-label="รายงานตรวจทาน" title="รายงานตรวจทาน"><FileCheck2 size={17}/></a>{['draft','importing'].includes(b.status)?<button className="button secondary small" onClick={()=>loadPreview(b.id).catch(e=>setError(e.message))}>ตรวจทาน / ทำต่อ</button>:<button className="icon-button" disabled={busy} onClick={()=>changeBatch(b,b.status==='committed'?'archive':'restore')} aria-label={b.status==='committed'?'เก็บออกจากการสืบค้น':'คืนชุดข้อมูล'} title={b.status==='committed'?'เก็บออกจากการสืบค้น':'คืนชุดข้อมูล'}>{b.status==='committed'?<Archive size={17}/>:<ArchiveRestore size={17}/>}</button>}<button className="icon-button danger" disabled={busy} onClick={()=>deleteBatch(b)} aria-label={'ลบชุดข้อมูลถาวร: '+b.filename} title="ลบชุดข้อมูลถาวร"><Trash2 size={17}/></button></div></td></tr>)}</tbody></table></div><div className="pagination"><div className="pagination-summary"><PageSizeSelect value={batchSize} onChange={setBatchSize} disabled={busy}/><span>{num(batchPaging.total)} ชุดข้อมูล</span></div><Pagination page={batchPaging.page} pages={batchPaging.pages} onChange={p=>{void fetchBatches(p).catch(e=>setError(e.message));}} disabled={busy}/></div></>:<div className="empty"><Layers size={32}/><h3>ยังไม่มีชุดข้อมูล</h3><p>ไฟล์ที่คุณอัปโหลดและประวัติการนำเข้าจะแสดงที่นี่</p><button className="button secondary" onClick={()=>navigate('upload')}>นำเข้า Excel</button></div>}</section></>:null}
 {tab==='trash'?<><section className="page-heading"><div><div className="eyebrow">จัดการรายชื่อที่นำออกจากทะเบียน</div><h1>ถังขยะรายชื่อ</h1><p>กู้คืนรายชื่อกลับสู่ทะเบียน หรือเลือกลบทิ้งถาวร</p></div><span className="count-badge">{num(trashResult.total)} รายชื่อ</span></section><div className="info-line banner"><Trash2 size={20}/><p>รายชื่อในถังขยะจะไม่ปรากฏในผลค้นหาและสถิติ กู้คืนได้ทุกเมื่อ ส่วนการลบทิ้งถาวรจะลบข้อมูลและประวัติที่เกี่ยวข้องโดยย้อนกลับไม่ได้</p></div><section className="card">{trashResult.items.length?<><div className="table-wrap"><table><thead><tr><th>ชื่อ–นามสกุล / ฉายา</th><th>ประเภท / ระดับ</th><th>สังกัด</th><th>จังหวัด / ปี พ.ศ.</th><th>จัดการ</th></tr></thead><tbody>{trashResult.items.map(r=><tr key={r.id}><td><strong>{r.title}{r.first_name} {r.last_name}</strong><small>{r.dharma_name||'ไม่ระบุฉายา'}</small></td><td>{r.category} ชั้น{r.level}<small>{r.sect||'ไม่ระบุนิกาย'}</small></td><td>{r.school||r.temple||'ไม่ระบุ'}<small>{r.filename}{r.batch_status==='archived'?' · ชุดข้อมูลถูกเก็บออก':''}</small></td><td>{r.province}<small>พ.ศ. {r.year}</small></td><td><div className="row-actions"><button className="button secondary small" disabled={busy} title="กู้คืนรายชื่อนี้กลับสู่ทะเบียน" aria-label={'กู้คืนรายชื่อ '+r.first_name+' '+r.last_name} onClick={()=>restoreRecord(r)}><ArchiveRestore size={15}/>กู้คืนรายชื่อ</button><button className="icon-button danger" disabled={busy} title="ลบทิ้งถาวร" aria-label={'ลบทิ้งถาวร '+r.first_name} onClick={()=>purgeRecord(r)}><Trash2 size={17}/></button></div></td></tr>)}</tbody></table></div><div className="pagination"><div className="pagination-summary"><PageSizeSelect value={trashSize} onChange={size=>{setTrashSize(size);setTrashResult(old=>({...old,page:1}));}} disabled={busy}/><span>แสดง {(trashResult.page-1)*trashSize+1}–{Math.min(trashResult.page*trashSize,trashResult.total)} จาก {num(trashResult.total)} รายชื่อ</span></div><Pagination page={trashResult.page} pages={trashResult.pages} onChange={fetchTrash} disabled={busy}/></div></>:<div className="empty"><Trash2 size={32}/><h3>ไม่มีรายชื่อในถังขยะ</h3><p>รายชื่อที่คุณย้ายออกจากทะเบียนจะแสดงที่นี่</p></div>}</section></>:null}
 {tab==='help'?<><section className="page-heading"><div><div className="eyebrow">เริ่มต้นใช้งาน</div><h1>จาก Excel สู่ทะเบียนที่ค้นหาได้</h1><p>เพิ่มทะเบียนจากทุกภาค จังหวัด ประเภท ชั้น และนิกาย โดยเลือกปี พ.ศ. ทุกครั้ง</p></div><a className="button primary" href="/api/passlist?action=template"><Download size={18}/>ดาวน์โหลดแม่แบบ</a></section><div className="help-grid">{[{n:'01',title:'จัดเตรียมบัญชีรายชื่อ',body:'ดาวน์โหลดแม่แบบ กรอกชื่อ ประเภท และระดับชั้นเป็นอย่างน้อย หรือใช้บัญชีเดิมที่มีหัวคอลัมน์ชื่อและนามสกุล เก็บเฉพาะรายชื่อผู้สอบได้ในไฟล์ .xlsx'}, {n:'02',title:'ระบุขอบเขตและปี พ.ศ.',body:'เลือกปี พ.ศ. เช่น 2569 หากไฟล์รวมหลายจังหวัด ให้เลือก “อ่านจากไฟล์” และระบุจังหวัดสนามสอบในคอลัมน์ หัวข้อ หรือชื่อชีต ภาคที่ไม่ระบุจะเติมจากตารางจังหวัด ส่วนนิกายเริ่มต้นใช้เติมเฉพาะเมื่อไฟล์ไม่ระบุ'}, {n:'03',title:'ตรวจทานก่อนนำเข้า',body:'ตรวจยอดแยกภาค จังหวัด นิกาย ประเภทและชั้น ดาวน์โหลดรายงานเพื่อตรวจทุกแถวผิดปกติ แถวที่ชื่อหรือประเภทไม่ครบต้องแก้ต้นฉบับก่อน หรือยืนยันแยกออก'}, {n:'04',title:'สืบค้นและปรับปรุง',body:'หลังยืนยันนำเข้า ค้นหาด้วยชื่อ นามสกุล ฉายา วัด หรือสำนักเรียน และกรองภาค จังหวัด นิกาย ปี ประเภท ระดับได้ คลิกชื่อเพื่อดูที่มาและแก้ไขพร้อมระบุเหตุผล'}].map(h=><article className="card help-step" key={h.n}><span>{h.n}</span><h2>{h.title}</h2><p>{h.body}</p></article>)}</div><section className="card faq"><h2>สิ่งที่ควรรู้</h2>{[['จังหวัดสนามสอบกับจังหวัดในไฟล์ต่างกันได้หรือไม่','ใช้จังหวัดสนามสอบจากคอลัมน์เฉพาะ หัวข้อ หรือชื่อชีต หากเลือกจังหวัดแบบเจาะจงจะตรวจให้ตรงกัน ส่วนคอลัมน์ “จังหวัด” ของบัญชีเก่าคงเป็นจังหวัดสังกัด เว้นแต่คุณติ๊กยืนยันให้ใช้เป็นจังหวัดสนามสอบเมื่อไม่มีข้อมูลชัดเจนกว่า'],['ไฟล์รวมหลายจังหวัดและสองนิกายใช้ได้อย่างไร','ใช้แม่แบบใหม่ กรอกจังหวัดสนามสอบ ภาค นิกาย ประเภท และชั้นในแต่ละแถว หรือระบุในหัวข้อ/ชื่อชีต เลือกจังหวัดเป็น อ่านจากไฟล์ ถ้าคอลัมน์จังหวัดในบัญชีเก่าคือจังหวัดสนามสอบจริง ให้ติ๊กยืนยันการใช้งานคอลัมน์นั้น'],['ภาคหรือนิกายไม่มีในไฟล์จะทำอย่างไร','เลือกค่าเริ่มต้นตอนอัปโหลดได้ ข้อมูลที่อ่านได้จากไฟล์จะใช้ก่อนค่าเริ่มต้น ถ้าไม่มีตำบล จังหวัดสังกัด หรือนิกาย ระบบจะเติมจากทะเบียนวัดอ้างอิงเมื่อจับคู่ชื่อและพื้นที่ได้เพียงรายการเดียว ระบบเติมภาคจากตารางจับคู่จังหวัดที่ผู้ดูแลให้ไว้เมื่อไฟล์ไม่ระบุ และคงภาคที่ระบุในไฟล์ไว้ และจะพักชื่อซ้ำ พื้นที่ไม่ตรง หรือนิกายขัดแย้งให้ตรวจทาน'],['ไฟล์เก่ารวม 6 กลุ่มในชีตเดียวใช้ได้หรือไม่','ใช้ได้เมื่อมีหัวข้อระบุ นักธรรม/ธรรมศึกษา และชั้น ตรี/โท/เอก ระบบอ่านหัวตารางใหม่ทุกกลุ่มและเก็บเลขแถวต้นฉบับไว้ ควรกระทบยอดกับบัญชีจริงก่อนยืนยัน'],['ข้อมูลซ้ำและข้อมูลไม่ครบจัดการอย่างไร','ระบบไม่ลบชื่อซ้ำอัตโนมัติ แถวที่ข้อมูลหลักซ้ำจะแจ้งข้อสังเกต และการอัปโหลดไฟล์เดิมในจังหวัดและปีเดิมจะไม่เพิ่มซ้ำ นามสกุลไม่ครบยังนำเข้าและแก้ภายหลังได้ ส่วนแถวที่ไม่มีชื่อ ประเภท หรือระดับจะไม่ผ่านเกณฑ์'],['อัปโหลดผิดชุดแก้ได้หรือไม่','ไปที่ชุดข้อมูลผู้ดูแล กดเก็บออกเพื่อซ่อนชุดจากการค้นหาและคืนได้ภายหลัง หรือกดไอคอนถังขยะเพื่อลบรายชื่อ ไฟล์ Excel และข้อมูลตรวจทานอย่างถาวร การลบต้องยืนยันและย้อนกลับไม่ได้'],['ข้อมูลเผยแพร่ให้คนทั่วไปแล้วหรือยัง','หน้าสืบค้นทั่วไปต้องกรอกชื่อและนามสกุลคู่กัน และเห็นเฉพาะชุดที่เผยแพร่แล้ว นิกายไม่ใช่เงื่อนไขการเผยแพร่หรือการค้นหา ผู้ดูแลเท่านั้นที่นำเข้า แก้ไข ดาวน์โหลดต้นฉบับ และเปลี่ยนการเผยแพร่ได้'],['นำเข้าอัตโนมัติทำงานอย่างไร','เลือกไฟล์แล้วกดเริ่มนำเข้าอัตโนมัติ ระบบอ่านหัวกระดาษและหัวคอลัมน์ จัดกลุ่มตามนิกาย ภาค จังหวัด ประเภท ชั้น และสำนักเรียน แล้วบันทึกและเผยแพร่เมื่อข้อมูลครบ ไม่มีคำเตือน และยอดสถิติตรงกัน ถ้าไม่ผ่านจะพักไว้ให้ผู้ดูแลตรวจ เติมนิกายได้จากทะเบียนสำนักเรียนส่วนกลางที่ชื่อตรงกัน ชื่อไม่ตรงจะพักตรวจทาน'],['สำรองข้อมูลได้อย่างไร','ดาวน์โหลดไฟล์ต้นฉบับและรายงานจากหน้าชุดข้อมูล หรือส่งออกผลการค้นหาเป็น CSV ได้ครั้งละไม่เกิน 10,000 รายชื่อ แนะนำกรองจังหวัดและปีในการส่งออก']].map(([q,a])=><details key={q}><summary>{q}</summary><p>{a}</p></details>)}</section></>:null}
 <footer className="page-footer"><span><BookOpen size={15}/>ธรรมทะเบียน <span className="footer-divider">/</span> ระบบสืบค้นผู้สอบได้นักธรรมและธรรมศึกษา</span><button className="text-button" onClick={()=>navigate('help')}>คู่มือการใช้งาน<ArrowUpRight size={14}/></button></footer><datalist id="central-school-options">{CENTRAL_SCHOOLS.map(s=><option key={s.name} value={s.name}>{s.code} · {s.sect}</option>)}</datalist><datalist id="region-options">{regionChoices.map(v=><option key={v} value={v}/>)}</datalist></main></div>
 {detail?<Modal title={editing?'แก้ไขข้อมูลรายชื่อ':'รายละเอียดทะเบียน'} onClose={()=>{if(!busy){setDetail(null);setEditing(false);}}}>{error?<div className="alert error" role="alert">{error}</div>:null}{editing?<form onSubmit={edit}><p className="muted">แก้ไขข้อมูลการสืบค้น พร้อมเก็บประวัติและไฟล์ต้นฉบับ</p><div className="two-col">{[['title','คำนำหน้า'],['first_name','ชื่อ *'],['last_name','นามสกุล'],['dharma_name','ฉายา'],['temple','วัด / องค์กร / สถานศึกษา'],['subdistrict','แขวง / ตำบล'],['district','เขต / อำเภอ']].map(([k,l])=><label className="field" key={k}><span>{l}</span><input name={k} defaultValue={String(detail.record[k]||'')} maxLength={500} required={k==='first_name'}/></label>)}<label className="field"><span>จังหวัด</span><select name="source_province" value={editProvince} onChange={e=>{const next=e.target.value;setEditProvince(next);setAutoSchool(true);setEditSchool(next?'คณะจังหวัด'+next:'');}}><option value="">เลือกจังหวัด</option>{PROVINCES.map(p=><option key={p} value={p}>{p}</option>)}</select></label><label className="field"><span>สำนักเรียน (เติมจากจังหวัด)</span><input name="school" value={editSchool} onChange={e=>setEditSchool(e.target.value)} maxLength={500} readOnly={autoSchool}/></label></div><input type="hidden" name="auto_school" value={autoSchool?'true':'false'} readOnly/><div className="two-col metadata-edit"><label className="field"><span>ภาค</span><input name="region" defaultValue={detail.record.region||''} list="region-options" placeholder="ไม่ระบุ" maxLength={100}/></label><label className="field"><span>นิกาย</span><select name="sect" defaultValue={detail.record.sect||''}><option value="">ไม่ระบุ</option>{SECTS.map(v=><option key={v} value={v}>{v}</option>)}</select></label></div><div className="two-col metadata-edit"><label className="field"><span>พื้นที่การศึกษา</span><select name="jurisdiction" defaultValue={String(detail.record.jurisdiction||'')}><option value="">ไม่ระบุ</option><option>ส่วนกลาง</option><option>ส่วนภูมิภาค</option></select></label><label className="field"><span>ชนิดสำนักเรียนส่วนกลาง</span><select name="school_kind" defaultValue={String(detail.record.school_kind||'')}><option value="">ไม่ระบุ</option><option>วัด</option><option>คณะเขต</option><option>คณะสงฆ์</option></select></label></div><label className="field"><span>หมายเหตุภายใน</span><textarea name="note" defaultValue={detail.record.note} maxLength={500}/></label><label className="field"><span>เหตุผลในการแก้ไข / หลักฐานยืนยันนิกาย *</span><textarea name="reason" required minLength={5} maxLength={500} placeholder="เช่น แก้การสะกดตามบัญชีต้นฉบับ"/></label><div className="modal-actions"><button type="button" className="button secondary" onClick={()=>setEditing(false)} disabled={busy}>ยกเลิก</button><button className="button primary" type="submit" disabled={busy}>{busy?<Loader2 size={17} className="spin"/>:<Check size={17}/>}บันทึกการแก้ไข</button></div></form>:<><span className="tag green">{detail.record.category} ชั้น{detail.record.level}</span><h2 className="person-name">{detail.record.title}{detail.record.first_name} {detail.record.last_name}</h2><p className="dharma-name">{detail.record.dharma_name||'ไม่ระบุฉายา'}</p><dl className="detail-grid">{[['เลข ปกศ.',certificateNumber(detail.record)],['ภาค',detail.record.region],['นิกาย',detail.record.sect],['สำนักเรียนคณะจังหวัด',studyCenterLabel(detail.record)],['ปีการสอบ พ.ศ.',detail.record.year],['ปี พ.ศ. เกิด',ageDisplay(detail.record.birth_year,detail.record.birth_year_estimated)],['อายุ ณ ปีที่สอบผ่าน',examAgeDisplay(detail.record.age_at_exam,detail.record.age_estimated)],...(detail.record.category==='นักธรรม'?[['พรรษา',vassaDisplay(detail.record.vassa,detail.record.category,detail.record.title)]]:[]),[affiliationLabel(detail.record.category),detail.record.temple],['แขวง / ตำบล',detail.record.subdistrict],['เขต / อำเภอ',detail.record.district],['สำนักเรียน',detail.record.school],['พื้นที่การศึกษา',String(detail.record.jurisdiction||'')],['ชนิดสำนักเรียน',String(detail.record.school_kind||'')],['จังหวัดสังกัด',detail.record.source_province],['หมายเหตุภายใน',detail.record.note]].map(([k,v])=><div key={String(k)}><dt>{k}</dt><dd>{String(v||'ไม่ระบุ')}</dd></div>)}</dl><div className="source-box"><h3><FileSpreadsheet size={17}/>ที่มาของข้อมูล</h3><p>{detail.record.filename}</p><small>ชีต {detail.record.sheet} · แถว {detail.record.source_row}</small><a href={'/api/passlist?action=source&id='+detail.record.batch_id} className="text-button"><Download size={15}/>ดาวน์โหลดต้นฉบับ</a></div>{detail.changes.length?<div className="change-log"><h3><History size={17}/>ประวัติการแก้ไข</h3>{detail.changes.map((c,i)=><p key={i}><small>{date(c.created_at)}</small>{JSON.parse(c.detail).reason}</p>)}</div>:null}<div className="modal-actions"><button className="button secondary" onClick={()=>setDetail(null)}>ปิด</button><button className="button secondary danger-text" disabled={busy} onClick={()=>trashRecord(detail.record)}><Trash2 size={17}/>ย้ายไปถังขยะ</button><button className="button primary" onClick={()=>beginEdit(detail.record)}><Pencil size={17}/>แก้ไขข้อมูล</button></div></>}</Modal>:null}
 </div></ThaiNumerals>
}
function Stat({icon,label,value,sub}:{icon:ReactNode;label:string;value:string;sub:string}){return <ThaiNumerals><article className="stat-card"><span className="stat-icon">{icon}</span><span className="stat-label">{label}</span><strong>{value}<small>{label==='ปีการสอบ'?' ปี':label==='จังหวัดที่มีข้อมูล'?' จังหวัด':' รายชื่อ'}</small></strong><span className="stat-sub">{sub}</span></article></ThaiNumerals>}
